//! Unicode property lookups for the regex escapes `\p{..}` and `\P{..}` (D1500), over the
//! tables in `props.rs` (generated by `scripts/gen-unicode.py`).
//!
//! Names are matched exactly (no loose matching), with the aliases ECMA-262 allows:
//! `General_Category`/`gc`, `Script`/`sc` and `Script_Extensions`/`scx` with a value, or a
//! lone General_Category value, binary property or (in `v` mode) property of strings.

use alloc::vec::Vec;

use super::props::{
    BINARY, DATA, GENERAL_CATEGORY, GENERAL_CATEGORY_GROUPS, SCRIPTS, SCX_EXPLICIT, STRINGS,
};

/// Why a lookup failed; the messages are QuickJS's.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum PropertyError {
    Name,
    Script,
    GeneralCategory,
}

impl PropertyError {
    pub fn message(self) -> &'static str {
        match self {
            PropertyError::Name => "unknown unicode property name",
            PropertyError::Script => "unknown unicode script",
            PropertyError::GeneralCategory => "unknown unicode general category",
        }
    }
}

/// The code points (sorted, disjoint inclusive ranges) and, for properties of strings,
/// the sequences of two or more code points.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Property {
    pub ranges: Vec<(u32, u32)>,
    pub strings: Vec<Vec<u32>>,
}

/// Looks up `\p{name}` (`value` empty) or `\p{name=value}`, as qjs does: `\p{Script}` is
/// an unknown script, `\p{Lu=}` is `\p{Lu}`. Properties of strings are only found with
/// `strings`.
pub fn lookup(name: &str, value: &str, strings: bool) -> Result<Property, PropertyError> {
    let set = |ranges| Property {
        ranges,
        strings: Vec::new(),
    };
    match name {
        "Script" | "sc" | "Script_Extensions" | "scx" => {
            let ext = name.starts_with("Script_") || name == "scx";
            script(value, ext).map(set).ok_or(PropertyError::Script)
        }
        "General_Category" | "gc" => general_category(value)
            .map(set)
            .ok_or(PropertyError::GeneralCategory),
        _ if !value.is_empty() => Err(PropertyError::Name),
        _ => {
            if let Some(r) = general_category(name) {
                return Ok(set(r));
            }
            if let Some(r) = binary(name) {
                return Ok(set(r));
            }
            if strings && let Some(p) = string_property(name) {
                return Ok(p);
            }
            Err(PropertyError::Name)
        }
    }
}

fn has_name(names: &str, name: &str) -> bool {
    names.split(',').any(|n| n == name)
}

/// A varint at `*p` in DATA.
fn varint(p: &mut usize) -> u32 {
    let mut v = 0;
    let mut shift = 0;
    loop {
        let b = DATA[*p];
        *p += 1;
        v |= ((b & 0x7F) as u32) << shift;
        if b < 0x80 {
            return v;
        }
        shift += 7;
    }
}

fn decode_set(off: u32) -> Vec<(u32, u32)> {
    let mut p = off as usize;
    let n = varint(&mut p);
    let mut out = Vec::with_capacity(n as usize);
    let mut prev = 0;
    for _ in 0..n {
        let lo = prev + varint(&mut p);
        let hi = lo + varint(&mut p);
        out.push((lo, hi));
        prev = hi + 1;
    }
    out
}

fn decode_sequences(off: u32) -> Vec<Vec<u32>> {
    let mut p = off as usize;
    let n = varint(&mut p);
    let mut out: Vec<Vec<u32>> = Vec::with_capacity(n as usize);
    for _ in 0..n {
        let prefix = varint(&mut p) as usize;
        let len = varint(&mut p);
        let mut s: Vec<u32> = match out.last() {
            Some(prev) => prev[..prefix].to_vec(),
            None => Vec::new(),
        };
        let mut last = s.last().copied().unwrap_or(0);
        for _ in 0..len {
            let z = varint(&mut p);
            let d = if z & 1 == 0 {
                (z >> 1) as i64
            } else {
                -(((z + 1) >> 1) as i64)
            };
            last = (last as i64 + d) as u32;
            s.push(last);
        }
        out.push(s);
    }
    out
}

/// The union of sorted range lists.
fn union(mut a: Vec<(u32, u32)>, b: &[(u32, u32)]) -> Vec<(u32, u32)> {
    a.extend_from_slice(b);
    normalize(a)
}

/// Sorts and merges overlapping or adjacent ranges.
fn normalize(mut v: Vec<(u32, u32)>) -> Vec<(u32, u32)> {
    crate::sort::sort_by(&mut v, |x, y| x.0 < y.0);
    let mut out: Vec<(u32, u32)> = Vec::with_capacity(v.len());
    for (lo, hi) in v {
        match out.last_mut() {
            Some(last) if lo <= last.1.saturating_add(1) => last.1 = last.1.max(hi),
            _ => out.push((lo, hi)),
        }
    }
    out
}

/// `a` minus `b`.
fn subtract(a: &[(u32, u32)], b: &[(u32, u32)]) -> Vec<(u32, u32)> {
    let mut out = Vec::new();
    let mut j = 0;
    for &(lo, hi) in a {
        let mut lo = lo;
        while j < b.len() && b[j].1 < lo {
            j += 1;
        }
        let mut k = j;
        while lo <= hi {
            if k >= b.len() || b[k].0 > hi {
                out.push((lo, hi));
                break;
            }
            if b[k].0 > lo {
                out.push((lo, b[k].0 - 1));
            }
            if b[k].1 >= hi {
                break;
            }
            lo = b[k].1 + 1;
            k += 1;
        }
    }
    out
}

fn general_category(value: &str) -> Option<Vec<(u32, u32)>> {
    if let Some(&(_, off)) = GENERAL_CATEGORY.iter().find(|(n, _)| has_name(n, value)) {
        return Some(decode_set(off));
    }
    let &(_, members) = GENERAL_CATEGORY_GROUPS
        .iter()
        .find(|(n, _)| has_name(n, value))?;
    let mut out = Vec::new();
    for m in members.split(',') {
        let &(_, off) = GENERAL_CATEGORY.iter().find(|(n, _)| has_name(n, m))?;
        out = union(out, &decode_set(off));
    }
    Some(out)
}

fn script(value: &str, extensions: bool) -> Option<Vec<(u32, u32)>> {
    let &(_, sc, scx) = SCRIPTS.iter().find(|(n, _, _)| has_name(n, value))?;
    let base = decode_set(sc);
    if !extensions {
        return Some(base);
    }
    // Code points listed in ScriptExtensions.txt have exactly the scripts listed there.
    let mut out = subtract(&base, &decode_set(SCX_EXPLICIT));
    if scx != u32::MAX {
        out = union(out, &decode_set(scx));
    }
    Some(out)
}

fn binary(name: &str) -> Option<Vec<(u32, u32)>> {
    match name {
        "Any" => return Some(alloc::vec![(0, 0x10FFFF)]),
        "ASCII" => return Some(alloc::vec![(0, 0x7F)]),
        "Assigned" => {
            let cn = general_category("Cn")?;
            return Some(subtract(&[(0, 0x10FFFF)], &cn));
        }
        _ => {}
    }
    let &(_, off) = BINARY.iter().find(|(n, _)| has_name(n, name))?;
    Some(decode_set(off))
}

fn string_property(name: &str) -> Option<Property> {
    if name == "RGI_Emoji" {
        let mut all = Property::default();
        for &(_, chars, seqs) in &STRINGS {
            all.ranges = union(all.ranges, &decode_set(chars));
            all.strings.extend(decode_sequences(seqs));
        }
        return Some(all);
    }
    let &(_, chars, seqs) = STRINGS.iter().find(|(n, _, _)| *n == name)?;
    Some(Property {
        ranges: decode_set(chars),
        strings: decode_sequences(seqs),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn contains(p: &Property, c: u32) -> bool {
        p.ranges.iter().any(|&(lo, hi)| lo <= c && c <= hi)
    }

    #[test]
    fn lookups() {
        let lu = lookup("Lu", "", false).unwrap();
        assert!(contains(&lu, 'A' as u32) && !contains(&lu, 'a' as u32));
        let l = lookup("gc", "Letter", false).unwrap();
        assert!(contains(&l, 'a' as u32) && contains(&l, 0x4E00) && !contains(&l, '1' as u32));
        let greek = lookup("Script", "Greek", false).unwrap();
        assert!(contains(&greek, 0x3B1) && !contains(&greek, 0x342));
        let greek_x = lookup("scx", "Grek", false).unwrap();
        assert!(contains(&greek_x, 0x342));
        let assigned = lookup("Assigned", "", false).unwrap();
        assert!(contains(&assigned, 'a' as u32) && !contains(&assigned, 0x378));
        assert!(contains(&lookup("space", "", false).unwrap(), ' ' as u32));
        assert_eq!(lookup("WSpace", "", false), Err(PropertyError::Name));
        assert_eq!(lookup("lu", "", false), Err(PropertyError::Name));
        assert_eq!(lookup("Script", "Foo", false), Err(PropertyError::Script));
        assert_eq!(
            lookup("General_Category", "", false),
            Err(PropertyError::GeneralCategory)
        );
        assert_eq!(lookup("RGI_Emoji", "", false), Err(PropertyError::Name));
        let flags = lookup("RGI_Emoji_Flag_Sequence", "", true).unwrap();
        assert!(flags.strings.contains(&alloc::vec![0x1F1E9, 0x1F1EA]));
        let rgi = lookup("RGI_Emoji", "", true).unwrap();
        assert!(contains(&rgi, 0x1F600));
        assert!(
            rgi.strings
                .contains(&alloc::vec![0x1F468, 0x200D, 0x1F469, 0x200D, 0x1F467])
        );
    }

    #[test]
    fn subtract_ranges() {
        assert_eq!(
            subtract(&[(0, 10), (20, 30)], &[(2, 3), (5, 25)]),
            alloc::vec![(0, 1), (4, 4), (26, 30)]
        );
        assert_eq!(subtract(&[(0, 10)], &[]), alloc::vec![(0, 10)]);
        assert_eq!(subtract(&[(5, 6)], &[(0, 10)]), alloc::vec![]);
    }
}
